import re

def parse_color(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not re.fullmatch(r'#([A-Fa-f0-9]{3}|[A-Fa-f0-9]{6})', text):
        raise ValueError("invalid color format")
    if len(text) == 4:
        # Expand each character to two
        r = int(text[1] * 2, 16)
        g = int(text[2] * 2, 16)
        b = int(text[3] * 2, 16)
    else:  # len 7
        r = int(text[1:3], 16)
        g = int(text[3:5], 16)
        b = int(text[5:7], 16)
    return (r, g, b)

def format_color(rgb):
    if not (isinstance(rgb, (tuple, list)) and len(rgb) == 3):
        raise ValueError("rgb must be a tuple or list of exactly three elements")
    for val in rgb:
        if not isinstance(val, int) or not (0 <= val <= 255):
            raise ValueError("each component must be an int between 0 and 255")
    r, g, b = rgb
    r_str = f"{r:02x}"
    g_str = f"{g:02x}"
    b_str = f"{b:02x}"
    if (r_str[0] == r_str[1] and 
        g_str[0] == g_str[1] and 
        b_str[0] == b_str[1]):
        return f"#{r_str[0]}{g_str[0]}{b_str[0]}"
    else:
        return f"#{r_str}{g_str}{b_str}"

