        return "0"
    parts = []
    digits = list(str(n))
    while len(digits) > 3:
        parts.insert(0, ''.join(digits[-3:]))
        digits = digits[:-3]
    parts.insert(0, ''.join(digits))
    return ','.join(parts)

def text_to_cents(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == "0.00":
        return 0
    sign = 1
    if text.startswith('-'):
        text = text[1:]
        sign = -1
    elif text.startswith('+'):
        raise ValueError("plus sign not allowed")
    if text == "0.00":
        if sign == -1:
            raise ValueError("negative zero not allowed")
        return 0
    parts = text.split('.')
    if len(parts) != 2:
        raise ValueError("invalid format")
    dollars_part, cents_part = parts
    if len(cents_part) != 2 or not cents_part.isdigit():
        raise ValueError("cents part must be two digits")
    if any(c not in ',0123456789' for c in dollars_part):
        raise ValueError("invalid character in dollars part")
    dollars_clean = dollars_part.replace(',', '')
    if not dollars_clean.isdigit():
        raise ValueError("invalid dollars part")
    if len(dollars_part) > 1 and dollars_part[0] == '0':
        raise ValueError("leading zero in dollars part")
    if dollars_part.count(',') != len(dollars_part.split(',')) - 1:
        raise ValueError("invalid commas in dollars part")
    dollars_value = int(dollars_clean)
    cents_value = int(cents_part)
    total_cents = dollars_value * 100 + cents_value
    if sign == -1 and dollars_value == 0 and cents_value == 0:
        raise ValueError("negative zero not allowed")
    return sign * total_cents
