def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if text == "":
        return []
    parts = text.split("&")
    result = []
    for part in parts:
        if not part:
            raise ValueError("Empty part")
        if part.count("=") != 1:
            raise ValueError("Part must have exactly one '='")
        key_encoded, value_encoded = part.split("=", 1)
        if not key_encoded:
            raise ValueError("Key cannot be empty")
        key = decode_component(key_encoded)
        value = decode_component(value_encoded)
        result.append((key, value))
    return result

def decode_component(s):
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "+":
            result.append(" ")
            i += 1
        elif c == "%":
            if i + 2 > len(s):
                raise ValueError("Incomplete percent escape")
            hex_part = s[i + 1:i + 3]
            if not all(ch in "0123456789ABCDEFabcdef" for ch in hex_part):
                raise ValueError("Invalid hex in percent escape")
            try:
                code = int(hex_part, 16)
            except ValueError:
                raise ValueError("Invalid hex in percent escape")
            if code > 0x7F:
                raise ValueError("Percent escape code above 0x7F")
            result.append(chr(code))
            i += 3
        else:
            if not (c.isalnum() or c in "-._~"):
                raise ValueError(f"Invalid character in component: {c!r}")
            result.append(c)
            i += 1
    return "".join(result)

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("Pairs must be a list or tuple")
    result = []
    for key, value in pairs:
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError("Key and value must be strings")
        if not key:
            raise ValueError("Key cannot be empty")
        for s in [key, value]:
            if any(ord(c) > 0x7F for c in s):
                raise ValueError("Non-ASCII character in key or value")
        encoded_key = encode_component(key)
        encoded_value = encode_component(value)
        result.append(f"{encoded_key}={encoded_value}")
    return "&".join(result)

def encode_component(s):
    result = []
    for c in s:
        if c.isalnum() or c in "-._~":
            result.append(c)
        elif c == " ":
            result.append("+")
        else:
            code = ord(c)
            result.append(f"%{code:02X}")
    return "".join(result)
