def phi(n):
    if not isinstance(n, int) or n < 1 or n > 10**12:
        raise ValueError("n must be an integer between 1 and 10^12")
    if n == 1:
        return 1
    m = n
    result = n
    primes = set()
    if m % 2 == 0:
        primes.add(2)
        while m % 2 == 0:
            m //= 2
    i = 3
    max_factor = math.isqrt(m)
    while i <= max_factor:
        if m % i == 0:
            primes.add(i)
            while m % i == 0:
                m //= i
            max_factor = math.isqrt(m)
        i += 2
    if m > 1:
        primes.add(m)
    for p in primes:
        result = result // p * (p - 1)
    return result

def totient_sum(limit):
    if not isinstance(limit, int) or limit < 1 or limit > 100000:
        raise ValueError("limit must be an integer between 1 and 100000")
    t = list(range(limit + 1))
    for i in itertools.chain([2], range(3, int(math.isqrt(limit)) + 1, 2)):
        if t[i] == i:
            for j in range(i, limit + 1, i):
                t[j] -= t[j] // i
    return sum(t[1:limit+1])
