def two_color(n, edges):
    # Validate n
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    # Validate edges
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError("each edge must be a 2-element list or tuple")
        a, b = edge
        if not isinstance(a, int) or not isinstance(b, int):
            raise ValueError("edge elements must be integers")
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError("edge elements must be in 0..n-1")
    # Check for loops (a == b)
    for a, b in edges:
        if a == b:
            return None
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    color = [-1] * n  # -1 means uncolored
    for start in range(n):
        if color[start] == -1:
            # Assign color 0 to start (for lex smallest)
            color[start] = 0
            # BFS
            queue = [start]
            import collections
            q = collections.deque(queue)
            while q:
                node = q.popleft()
                for neighbor in adj[node]:
                    if color[neighbor] == -1:
                        color[neighbor] = 1 - color[node]
                        q.append(neighbor)
                    elif color[neighbor] == color[node]:
                        return None
    return color
