    in_degree = [0] * n
    out_degree = [0] * n
    adj = [[] for _ in range(n)]
    for u, v in edges:
        out_degree[u] += 1
        in_degree[v] += 1
        adj[u].append(v)

    # Sort adjacency lists
    for u in range(n):
        adj[u].sort()

    # Check for Euler trail conditions
    start_node = None
    diff_counts = {}
    for u in range(n):
        diff = out_degree[u] - in_degree[u]
        if diff != 0:
            if diff not in diff_counts:
                diff_counts[diff] = 0
            diff_counts[diff] += 1

    if len(diff_counts) > 2:
