        start_node = [u for u in range(n) if out_degree[u] - in_degree[u] == 1][0]
    elif all(out_degree[u] - in_degree[u] == 0 for u in range(n)):
        # Find smallest node with at least one edge
        if not edges:
            return []
        start_node = min(u for u in range(n) if out_degree[u] > 0)
    else:
        return None

    # Hierholzer's algorithm with lex smallest path
    # Convert adjacency lists to deques for efficient popping
    from collections import deque
    adj_deques = [deque(adj[u]) for u in range(n)]

    stack = [start_node]
    path = []
    while stack:
        u = stack[-1]
        if adj_deques[u]:
            v = adj_deques[u].popleft()
            stack.append(v)
        else:
            path.append(stack.pop())

    # The path is built in reverse, so reverse it
    path.reverse()

    # Check if all edges are used (in case of disconnected components)
    if len(path) != len(edges) + 1:
        return None

