        raise ValueError

    x_coords = []
    y_coords = []

    for p in points:
        if not isinstance(p, (tuple, list)) or len(p) != 2:
            raise ValueError
        x, y = p
        if not (isinstance(x, int) and type(x) is int):
            raise ValueError
        if not (isinstance(y, int) and type(y) is int):
            raise ValueError
        x_coords.append(x)
        y_coords.append(y)

    x_coords.sort()
    y_coords.sort()
    n = len(points)
    median_x = x_coords[(n - 1) // 2]
    median_y = y_coords[(n - 1) // 2]

    total_distance = 0
    for x, y in points:
        total_distance += abs(median_x - x) + abs(median_y - y)

    return (median_x, median_y, total_distance)

