import sys
import collections

def tree_centers(n, edges):
    if not isinstance(n, int) or n < 1 or n > 100000:
        raise ValueError
    if not (isinstance(edges, (list, tuple)) and len(edges) == n - 1):
        raise ValueError
    for edge in edges:
        if not (isinstance(edge, (list, tuple)) and len(edge) == 2):
            raise ValueError
        for node in edge:
            if not isinstance(node, int) or not (0 <= node < n):
                raise ValueError

    def bfs(start):
        visited = [False] * n
        distance = [0] * n
        queue = collections.deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[node] + 1
                    queue.append(neighbor)
        max_dist = max(distance)
        farthest_nodes = [i for i in range(n) if distance[i] == max_dist]
        return farthest_nodes[0], max_dist

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    u, _ = bfs(0)
    v, diameter = bfs(u)
    if diameter == 0:
        return ([0], 0)
    if diameter == 1:
        return ([0, 1], 1)

    radius = (diameter + 1) // 2
    def find_centers(start):
        visited = [False] * n
        distance = [0] * n
        queue = collections.deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[node] + 1
                    queue.append(neighbor)
        target = (diameter - 1) // 2
        centers = [i for i in range(n) if distance[i] == target]
        if diameter % 2 == 0:
            return centers
        else:
            return centers + [i for i in range(n) if distance[i] == target + 1]

    centers = find_centers(u)
    return (sorted(centers), radius)
