def robot_walk(grid, commands):
    if not isinstance(grid, (list, tuple)) or not grid:
        raise ValueError
    if not all(isinstance(row, str) and row for row in grid):
        raise ValueError
    if len(set(len(row) for row in grid)) != 1:
        raise ValueError
    if any(c not in ('.', '#', 'S') for row in grid for c in row):
        raise ValueError
    s_pos = None
    for r, row in enumerate(grid):
        if 'S' in row:
            if s_pos is not None:
                raise ValueError
            s_pos = (r, row.index('S'))
    if s_pos is None:
        raise ValueError
    if any(c not in 'LRF' for c in commands):
        raise ValueError

    directions = [(-1, 0, 'N'), (0, 1, 'E'), (1, 0, 'S'), (0, -1, 'W')]
    dr, dc, facing = directions[0]
    row, col = s_pos
    visited = {(row, col)}
    dir_idx = 0

    for cmd in commands:
        if cmd == 'L':
            dir_idx = (dir_idx - 1) % 4
            dr, dc, facing = directions[dir_idx]
        elif cmd == 'R':
            dir_idx = (dir_idx + 1) % 4
            dr, dc, facing = directions[dir_idx]
        elif cmd == 'F':
            new_row, new_col = row + dr, col + dc
            if (0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and
                grid[new_row][new_col] != '#'):
                row, col = new_row, new_col
                visited.add((row, col))

    return (row, col, facing, len(visited))
