    for x in nums:
        if not isinstance(x, int):
            raise ValueError("All elements must be integers.")
    if n > 100000:
        raise ValueError("Input size exceeds maximum of 100000 elements.")

    current_max = nums[0]
    best = nums[0]
    current_start = 0
    best_i = 0
    best_j = 0

    for i in range(1, n):
        if current_max + nums[i] > nums[i]:
            current_max += nums[i]
        else:
            current_max = nums[i]
            current_start = i
        if current_max > best or (current_max == best and current_start < best_i) or (current_max == best and current_start == best_i and i < best_j):
            best = current_max
            best_i = current_start
            best_j = i
    return (best, best_i, best_j)
