def stair_ways(n, steps, broken):
    MOD = 10**9 + 7
    if not isinstance(n, int) or n < 0 or n > 100000:
        raise ValueError
    if not isinstance(steps, (list, tuple, set)):
        raise ValueError
    if len(steps) == 0 or (len(steps) > 10 or len(set(steps)) != len(steps)):
        raise ValueError
    for s in steps:
        if isinstance(s, bool) or not isinstance(s, int):
            raise ValueError
        if s < 1 or s > 100:
            raise ValueError
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError
    broken_set = set(broken)
    for b in broken_set:
        if not (1 <= b <= n - 1):
            raise ValueError
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            dp[i] = 0
        else:
            total = 0
            for s in steps:
                if s <= i:
                    total += dp[i - s]
            dp[i] = total % MOD
    return dp[n]
