    for b in broken_set:
        if not (1 <= b <= n - 1):
            raise ValueError
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            dp[i] = 0
        else:
            total = 0
            for s in steps:
                if s <= i:
                    total += dp[i - s]
            dp[i] = total % MOD
    return dp[n]

