        '5': '.....', '6': '-....', '7': '--...', '8': '---..', '9': '----.'
    }
    inv_morse_dict = {v: k for k, v in morse_dict.items()}

    if not code:
        return ""

    # Split into words
    words = code.split(' / ')
    for word in words:
        if not word:
            raise ValueError
        # Split into Morse codes
        codes = word.split(' ')
        for c in codes:
            if c not in inv_morse_dict:
