def cidr_range(text):
    import re

    # Validate the input format
    if not re.fullmatch(r'\d+\.\d+\.\d+\.\d+/\d+', text):
        raise ValueError("Invalid CIDR format")

    ip_part, prefix_part = text.split('/')

    # Validate IP part
    ip_octets = ip_part.split('.')
    if len(ip_octets) != 4:
        raise ValueError("Invalid IP part")
    for octet in ip_octets:
        if not octet.isdigit():
            raise ValueError("Invalid octet")
        num = int(octet)
        if num < 0 or num > 255:
            raise ValueError("Octet out of range")
        if len(octet) > 1 and octet[0] == '0':
            raise ValueError("Leading zero in octet")

    # Validate prefix
    if not prefix_part.isdigit():
        raise ValueError("Invalid prefix")
    prefix = int(prefix_part)
    if prefix < 0 or prefix > 32:
        raise ValueError("Prefix out of range")

    # Convert IP to integer
    ip_int = 0
    for octet in ip_octets:
        ip_int = (ip_int << 8) | int(octet)

    # Compute mask
    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
    first = ip_int & mask
    last = first | (~mask & 0xFFFFFFFF)
    size = 2 ** (32 - prefix)

    # Convert first and last to dotted format
    def int_to_ip(x):
        return '.'.join(str((x >> i) & 0xFF) for i in [24, 16, 8, 0])

    return (int_to_ip(first), int_to_ip(last), size)

