    match = re.match(pattern, text)
    if not match:
        raise ValueError("Invalid 12-hour format.")
    hour, minute, period = match.groups()
    hour = int(hour)
    minute = int(minute)
    if not (1 <= hour <= 12) or not (0 <= minute <= 59):
        raise ValueError("Hour or minute out of range.")
    if period == "AM":
        if hour == 12:
            hour_24 = 0
        else:
            hour_24 = hour
    else:  # PM
        if hour == 12:
            hour_24 = 12
        else:
            hour_24 = hour + 12
    return f"{hour_24:02d}:{minute:02d}"

def to_12h(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    pattern = r"^([0-1][0-9]|2[0-3]):([0-5][0-9])$"
    match = re.match(pattern, text)
    if not match:
        raise ValueError("Invalid 24-hour format.")
    hour, minute = match.groups()
    hour = int(hour)
    minute = int(minute)
    if not (0 <= hour <= 23) or not (0 <= minute <= 59):
        raise ValueError("Hour or minute out of range.")
    if hour == 0:
        period = "AM"
        hour_12 = 12
    elif 1 <= hour < 12:
        period = "AM"
        hour_12 = hour
    elif hour == 12:
        period = "PM"
        hour_12 = 12
    else:  # 13 <= hour <= 23
        period = "PM"
        hour_12 = hour - 12
    return f"{hour_12}:{minute:02d} {period}"

