def manhattan_center(points):
    # Validate input
    if not isinstance(points, (list, tuple)):
        raise ValueError
    if len(points) == 0:
        raise ValueError
    for point in points:
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            raise ValueError
        x, y = point
        if type(x) is not int or type(y) is not int:
            raise ValueError

    # Extract x and y coordinates
    x_coords = [x for x, y in points]
    y_coords = [y for x, y in points]

    # Sort the coordinates to find medians
    x_coords.sort()
    y_coords.sort()

    n = len(points)
    median_index = (n - 1) // 2

    # Find the median x and y
    x = x_coords[median_index]
    y = y_coords[median_index]

    # Calculate total Manhattan distance
    total = 0
    for px in x_coords:
        total += abs(x - px)
    for py in y_coords:
        total += abs(y - py)

    return (x, y, total)

