def apply_ledger(events):
    if not isinstance(events, (list, tuple)):
        raise ValueError
    balance = 0
    rejected = 0
    fees = 0

    for event in events:
        if not isinstance(event, (list, tuple)):
            raise ValueError
        if not event:
            raise ValueError
        cmd = event[0]
        if cmd == "deposit":
            if len(event) != 2:
                raise ValueError
            amount = event[1]
            if not isinstance(amount, int) or isinstance(amount, bool):
                raise ValueError
            if amount < 1:
                raise ValueError
            balance += amount
        elif cmd == "withdraw":
            if len(event) != 2:
                raise ValueError
            amount = event[1]
            if not isinstance(amount, int) or isinstance(amount, bool):
                raise ValueError
            if amount < 1:
                raise ValueError
            if balance >= amount:
                balance -= amount
            else:
                new_balance = balance - amount
                if new_balance >= -500:
                    balance = new_balance
                    fees += 25
                else:
                    rejected += 1
        elif cmd == "month":
            if len(event) != 1:
                raise ValueError
            if balance < 0:
                charge = (-balance * 2) // 100
                balance -= charge
                fees += charge
        else:
            raise ValueError
    return (balance, rejected, fees)
