    out_degree = [0] * n
    adj = defaultdict(list)

    for a, b in edges:
        out_degree[a] += 1
        in_degree[b] += 1
        adj[a].append(b)

    # Check for Eulerian trail conditions
    start_candidates = []
    end_candidates = []
    for v in range(n):
        diff = out_degree[v] - in_degree[v]
        if diff == 1:
            start_candidates.append(v)
        elif diff == -1:
            end_candidates.append(v)
        elif diff != 0:
            return None

    if len(start_candidates) > 1 or len(end_candidates) > 1 or len(start_candidates) != len(end_candidates):
        return None

    # Determine start vertex
    if start_candidates:
        start = start_candidates[0]
    else:
        # All degrees balanced, pick smallest vertex with edges
        for v in range(n):
            if out_degree[v] > 0:
                start = v
                break
        else:
            return []

    # Sort adjacency lists
    for v in adj:
        adj[v].sort()

    # Hierholzer's algorithm
    stack = [start]
    path = []
    while stack:
        current = stack[-1]
        if adj[current]:
            next_v = adj[current].pop(0)  # Pop smallest unused edge
            stack.append(next_v)
        else:
            path.append(stack.pop())

    # Reverse to get the correct order
    path.reverse()
    return path if len(path) == len(edges) + 1 else None

