def lcs(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError

    m, n = len(a), len(b)
    L = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            if a[i] == b[j]:
                L[i][j] = L[i+1][j+1] + 1
            else:
                L[i][j] = max(L[i+1][j], L[i][j+1])

    i = j = 0
    result = []
    while i < m and j < n and L[i][j] > 0:
        possible_chars = set()
        for k in range(i, m):
            if a[k] in b[j:]:
                possible_chars.add(a[k])
        for c in sorted(possible_chars):
            x = a.find(c, i)
            y = b.find(c, j)
            if x != -1 and y != -1 and L[x+1][y+1] == L[i][j] - 1:
                result.append(c)
                i, j = x + 1, y + 1
                break
    return ''.join(result)
