def elevator_stops(start, requests, direction):
    # Input validation
    if not isinstance(start, int) or not (0 <= start <= 1000):
        raise ValueError
    if not isinstance(requests, (list, tuple)):
        raise ValueError
    for req in requests:
        if not isinstance(req, int) or not (0 <= req <= 1000):
            raise ValueError
    if direction not in ("up", "down"):
        raise ValueError

    # Remove duplicates and process requests
    unique_requests = list(set(requests))
    stops = []
    distance = 0
    current = start

    # Serve current floor if requested
    if current in unique_requests:
        stops.append(current)
        unique_requests.remove(current)

    # Determine up_floors and down_floors based on direction
    if direction == "up":
        up_floors = [f for f in unique_requests if f > current]
        down_floors = [f for f in unique_requests if f < current]
        up_floors.sort()
    else:  # direction is "down"
        up_floors = [f for f in unique_requests if f < current]
        down_floors = [f for f in unique_requests if f > current]
        up_floors.sort(reverse=True)

    # Serve up_floors
    if up_floors:
        for floor in up_floors:
            stops.append(floor)
            distance += abs(floor - current)
            current = floor

    # Serve down_floors if any
    if down_floors:
        # Sort down_floors based on direction (for "up" dir, they are lower, sorted ascendingly)
        if direction == "up":
            down_floors.sort(reverse=True)  # to reach nearest first when moving down
        else:
            down_floors.sort()  # to reach nearest first when moving up after turn
        for floor in down_floors:
            stops.append(floor)
            distance += abs(floor - current)
            current = floor

    return (stops, distance)
